import sys, json, re
d = json.load(sys.stdin)["body"]
calls = [m for m in d.get("messages", []) if m.get("type") == "tool_call"]
if not calls:
    sys.stdout.write(json.dumps({"messages": []})); sys.exit(0)
c = calls[0]
args = json.loads(c.get("text", "{}")).get("arguments", {})
if isinstance(args, str):
    args = json.loads(args or "{}")
expr = str(args.get("expr", "")).strip()
if expr and re.fullmatch(r"[0-9.\s+\-*/()]+", expr):
    try:
        val = str(eval(expr, {"__builtins__": {}}, {}))
    except Exception as e:
        val = "error: %s" % e
else:
    val = "refused: only arithmetic allowed"
result = {"origin": "tool", "type": "tool_result", "id": c.get("id", "call"),
          "text": "%s = %s" % (expr, val)}
sys.stdout.write(json.dumps({"messages": [c, result]}))
